def __find_main_volume_view_registration_window(timeout: int=3000, retries: int=2):
    """Searches for the main VolumeView Registration window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the volume_view_registration_functions.py file

    :param int timeout: Time to wait for the main registration window object to be found
    :param int retries: Number of times to retry
    :return: True or False
    :rtype: bool
    """
    # Squish normally fails to find the VolumeView Registration window on the first attempt, but finds the window object the second time
    for i in range(retries):
        try:
            return True if CommonActions.find_object(VolumeViewRegistrationObjects.main_Volume_View_Registration_Window, timeout) is not None else False
        except Exception as e:
            print(f"Unable to find Volume View Registration window. Attempt no. {i+1}. Error: {e} ")

def __find_volume_view_inaccurate_registration_warning_dialog(timeout: int = 2000):
    """Searches for the Inaccurate Registration Warning Dialog. Returns True if successfully located.

    :param int timeout: Time to wait (in milliseconds) for the Inaccurate registration warning dialog to appear
    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewRegistrationObjects.volume_View_Inaccurate_Registration_Warning_Dialog, timeout) is not None else False

def __find_volume_view_registration_approval_dialog():
    """Searches for the Registration Approval Dialog. Returns True if successfully located.

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(VolumeViewRegistrationObjects.volume_View_Registration_Approval_Window) is not None else False

def __locate_reference_checkbox_by_child_object_index(childObjIndex: int) -> object:
    """Searches Reference pane child objects based on the positional index and finds the checkbox within
    the list of child objects. Returns object if successfully located. Assumes that the ordering of the
    child objects remains constant.

    Used for checkboxes that don't have a unique object property, but can be identified by drilling down
    the object tree and narrowing the search within a specific pane.

    :param int childObjIndex: Index of the WindowsControl child object in the pane object to be searched
    :return: found object
    :rtype: object
    """
    if __find_main_volume_view_registration_window():
        reference_pane_obj_list = CommonActions.get_child_objects(VolumeViewRegistrationObjects.volume_View_Reference_Pane)

        if len(reference_pane_obj_list) > 0:
            checkbox_object = reference_pane_obj_list[childObjIndex]
            return checkbox_object

