@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def wait_for_volume_view_reconstruction_pane(wait_timeout: int) -> bool:
    """Waits for the main VolumeView Registration Reconstruction pane to exist. Returns True if successfully located.
    """
    return True if CommonActions.wait_for_object_exists(VolumeViewRegistrationObjects.volume_View_Reconstruction_Pane, wait_timeout) is not None else False

