@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)   #TODO JC - set context as XVI_APP_NAME or XVI_REGISTRATION_APP_NAME?
def check_volume_view_registration_reference_clipbox_locked_context_menu_item() -> None:
    """Locates the main VolumeView Registration window > then left mouse click on the Clipbox button in the
    Reference pane, followed by the Locked context menu item only if its unchecked and enabled
    """
    if __find_main_volume_view_registration_window():
        CommonActions.left_click_object_no_move(VolumeViewRegistrationObjects.volume_View_Reference_Clipbox_Button)

        locked_context_menu_state = CommonActions.get_checkbox_state(VolumeViewRegistrationObjects.volume_View_Reference_Clipbox_Context_Menu)
        if not locked_context_menu_state:
            CommonActions.left_click_object_no_move(VolumeViewRegistrationObjects.volume_View_Reference_Clipbox_Context_Menu)
        else:
            # Click away from context menu if locked context menu item already checked
            clipboard_button = CommonActions.find_object(VolumeViewRegistrationObjects.volume_View_Reference_Clipbox_Button)
            CommonActions.mouse_press_hold_and_release_with_negative_y_offset(clipboard_button, yOffsetValue=20, mousePressDuration=0.5)

@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def uncheck_volume_view_registration_reference_clipbox_locked_context_menu_item() -> None:
    """Locates the main VolumeView Registration window > then left mouse click on the Clipbox button in the
    Reference pane, followed by the Locked context menu item only if its checked and enabled
    """
    if __find_main_volume_view_registration_window():
        CommonActions.left_click_object_no_move(VolumeViewRegistrationObjects.volume_View_Reference_Clipbox_Button)

        locked_context_menu_state = CommonActions.get_checkbox_state(VolumeViewRegistrationObjects.volume_View_Reference_Clipbox_Context_Menu)
        if locked_context_menu_state:
            CommonActions.left_click_object_no_move(VolumeViewRegistrationObjects.volume_View_Reference_Clipbox_Context_Menu)
        else:
            # Click away from context menu if locked context menu item already unchecked
            clipboard_button = CommonActions.find_object(VolumeViewRegistrationObjects.volume_View_Reference_Clipbox_Button)
            CommonActions.mouse_press_hold_and_release_with_negative_y_offset(clipboard_button, yOffsetValue=20, mousePressDuration=0.5)

