def select_volume_view_registration_method_manual() -> None:
    """Locates the main VolumeView Registration window > then left mouse click on the Registration Method Combobox and use
    the keyboard shortcut (first letter of method name) to select the Manual method
    """
    if __find_main_volume_view_registration_window():
        CommonActions.left_click_object_no_move(VolumeViewRegistrationObjects.volume_View_Registration_Method_ComboBox)
        CommonActions.press_key_sequence("M")
        CommonActions.press_enter_key()

