def edit_volume_view_registration_rotation_x_textfield(valueToSet: str) -> None:
    """Locates the main VolumeView Registration window > clears the existing text in the Rotation X field and enters the specified text

    :param str valueToSet: Value to be entered as a text string
    """
    ROTATION_X_FIELD_OBJ_IDX = 5 # Registration Rotation X field object is index no. 5 in the list of Rotation pane child objects
    registration_rotation_x_field = __locate_registration_rotation_field_by_child_object_index(childObjIndex=ROTATION_X_FIELD_OBJ_IDX)
    CommonActions.left_click_object_no_move(registration_rotation_x_field)
    CommonActions.press_key_sequence_ctrl_a()
    CommonActions.press_delete_key()
    CommonActions.type_in_textfield(registration_rotation_x_field, valueToSet)

