@deco.set_separate_app_context(application_name=XVI_REGISTRATION_APP_NAME)
def click_volume_view_inaccurate_registration_yes_button(waitTimout: int = 2000) -> None:
    """Locates the main VolumeView Registration window and Inaccurate Registration Warning Dialog >
    then left mouse click on the Yes button only if its enabled

    :param int waitTimeout: Time to wait (in milliseconds) for the Inaccurate registration warning dialog to appear
    """
    try:
        if __find_volume_view_inaccurate_registration_warning_dialog(timeout=waitTimout):
            CommonActions.left_click_object_no_move(VolumeViewRegistrationObjects.volume_View_Inaccurate_Registration_Warning_Yes_Button)
    except FailedToFindObject:
        pass

